import subprocess, re, pathlib
branches=['rachel','monica','phoebe','joey','chandler','ross']
allcommits=[]
for b in branches:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%H%x00%B%x1e'], text=True)
    for chunk in out.split('\x1e'):
        if not chunk.strip(): continue
        sha, body = chunk.split('\x00',1)
        if re.search(r'^Friend-Message:\s*1\s*$', body, re.M):
            allcommits.append(sha.strip())
src=set()
for f in pathlib.Path('.').glob('S*/*.md'):
    for line in f.read_text().splitlines():
        m=re.match(r'Source:\s*friend/\w+\s*@\s*([0-9a-f]+)', line)
        if m: src.add(m.group(1))
missing=[c for c in allcommits if c not in src]
print('commits',len(allcommits),'sources',len(src),'missing',len(missing))
